from pydantic import BaseModel, validator


class Stock(BaseModel):
    quantity: int = -1

    class Config:
        validate_all = True

    @validator("quantity")
    def quantity_must_be_nonneg(cls, v):
        if v < 0:
            raise ValueError("quantity must be >= 0")
        return v

